// FMAs instead of one, and the inner-loop shared addresses are
// strength-reduced to constant-stride pointer increments, removing the
// per-FMA integer address arithmetic that dominated the old inner loop.
.visible .entry conv2d_kernel(
    .param .u64 param_in,
    .param .u64 param_w,
    .param .u64 param_b,
    .param .u64 param_out
)
{
    .reg .b64 %rd_in, %rd_w, %rd_b, %rd_out, %rd_addr, %rd_obase;
    .reg .b32 %r_tid, %r_tx, %r_ty, %r_bx, %r_by, %r_n;
    .reg .b32 %r_k, %r_oh0, %r_ow0, %r_oh, %r_ow;
    .reg .b32 %r_in_base, %r_wbase, %r_smin, %r_smw;
    .reg .b32 %r_idx, %r_c, %r_r, %r_col, %r_ih, %r_iw;
    .reg .b32 %r_t0, %r_t1, %r_kh, %r_kw, %r_row0, %r_col0;
    .reg .b32 %r_iptr, %r_iptr1, %r_iptr2, %r_ip;
    .reg .b32 %r_wptr1, %r_wptr2, %r_wp;
    .reg .f32 %f_acc0, %f_acc1, %f_acc2, %f_acc3;
    .reg .f32 %f_v, %f_w0, %f_w1, %f_w2, %f_w3;
    .reg .f32 %f_b0, %f_b1, %f_b2, %f_b3;
    .reg .pred %p, %p1, %p2, %p_skip;
    // 55*55*3*4 = 36300 bytes input window, then 4*363*4 = 5808 bytes
    // of weights for one 4-filter group (42108 bytes total, still under
    // the 48KB static shared-memory limit).
    .shared .align 16 .b8 smem[42108];
    ld.param.u64 %rd_in, [param_in];
    ld.param.u64 %rd_w, [param_w];
    ld.param.u64 %rd_b, [param_b];
    ld.param.u64 %rd_out, [param_out];
    mov.u32 %r_tid, %tid.x;
    mov.u32 %r_bx, %ctaid.x;
    mov.u32 %r_by, %ctaid.y;
    mov.u32 %r_n, %ctaid.z;
    // Thread -> output position inside the 12x12 tile.
    rem.u32 %r_tx, %r_tid, 12;
    div.u32 %r_ty, %r_tid, 12;
    // Tile origin in output coordinates.
    mul.lo.u32 %r_ow0, %r_bx, 12;
    mul.lo.u32 %r_oh0, %r_by, 12;
    // Shared memory bases.
    mov.u32 %r_smin, smem;
    add.u32 %r_smw, %r_smin, 36300;
    // Per-image input base element offset: n * 3 * 224 * 224.
    mul.lo.u32 %r_in_base, %r_n, 150528;
    // ---- Cooperative load of the 55x55x3 input window (zero-padded) ----
    mov.u32 %r_idx, %r_tid;
LOAD_IN_LOOP:
    setp.ge.u32 %p, %r_idx, 9075;
    @%p bra LOAD_IN_DONE;
    // idx -> (c, r, col) with r, col in [0,55)
    div.u32 %r_c, %r_idx, 3025;
    mul.lo.u32 %r_t0, %r_c, 3025;
    sub.u32 %r_t1, %r_idx, %r_t0;
    div.u32 %r_r, %r_t1, 55;
    mul.lo.u32 %r_t0, %r_r, 55;
    sub.u32 %r_col, %r_t1, %r_t0;
    // ih = oh0*4 + r - 2, iw = ow0*4 + col - 2 (unsigned wrap marks negatives)
    mul.lo.u32 %r_t0, %r_oh0, 4;
    add.u32 %r_t0, %r_t0, %r_r;
    sub.u32 %r_ih, %r_t0, 2;
    mul.lo.u32 %r_t0, %r_ow0, 4;
    add.u32 %r_t0, %r_t0, %r_col;
    sub.u32 %r_iw, %r_t0, 2;
    mov.f32 %f_v, 0f00000000;
    setp.ge.u32 %p1, %r_ih, 224;
    setp.ge.u32 %p2, %r_iw, 224;
    or.pred %p, %p1, %p2;
    @%p bra STORE_SM_IN;
    // offset = in_base + c*50176 + ih*224 + iw
    mul.lo.u32 %r_t0, %r_c, 50176;
    add.u32 %r_t0, %r_t0, %r_in_base;
    mul.lo.u32 %r_t1, %r_ih, 224;
    add.u32 %r_t0, %r_t0, %r_t1;
    add.u32 %r_t0, %r_t0, %r_iw;
    mul.wide.u32 %rd_addr, %r_t0, 4;
    add.u64 %rd_addr, %rd_addr, %rd_in;
    ld.global.f32 %f_v, [%rd_addr];
STORE_SM_IN:
    mul.lo.u32 %r_t0, %r_idx, 4;
    add.u32 %r_t0, %r_t0, %r_smin;
    st.shared.f32 [%r_t0], %f_v;
    add.u32 %r_idx, %r_idx, 144;
    bra LOAD_IN_LOOP;
LOAD_IN_DONE:
    bar.sync 0;
    // Output coordinates for this thread (fixed across the filter loop).
    add.u32 %r_oh, %r_oh0, %r_ty;
    add.u32 %r_ow, %r_ow0, %r_tx;
    setp.ge.u32 %p1, %r_oh, 55;
    setp.ge.u32 %p2, %r_ow, 55;
    or.pred %p_skip, %p1, %p2;
    // Sliding window origin inside the shared tile for this thread.
    mul.lo.u32 %r_row0, %r_ty, 4;
    mul.lo.u32 %r_col0, %r_tx, 4;
    // Byte address of shared input element (c=0, row0, col0); constant
    // across the filter loop, inner strides applied by pointer increments.
    mul.lo.u32 %r_t0, %r_row0, 55;
    add.u32 %r_t0, %r_t0, %r_col0;
    mul.lo.u32 %r_t0, %r_t0, 4;
    add.u32 %r_iptr, %r_t0, %r_smin;
    // Byte address of the output element for k=0:
    // out + (((n*96)*55 + oh)*55 + ow) * 4.
    mul.lo.u32 %r_t0, %r_n, 96;
    mul.lo.u32 %r_t0, %r_t0, 55;
    add.u32 %r_t0, %r_t0, %r_oh;
    mul.lo.u32 %r_t0, %r_t0, 55;
    add.u32 %r_t0, %r_t0, %r_ow;
    mul.wide.u32 %rd_obase, %r_t0, 4;
    add.u64 %rd_obase, %rd_obase, %rd_out;
    // ---- Loop over the 96 filters in register-blocked groups of 4 ----
    mov.u32 %r_k, 0;
LOOP_K:
    // Cooperative load of the 4*363 = 1452 weights of filters k..k+3
    // (consecutive filters are contiguous in the weight tensor).
    mul.lo.u32 %r_wbase, %r_k, 363;
    mov.u32 %r_idx, %r_tid;
LOAD_W_LOOP:
    setp.ge.u32 %p, %r_idx, 1452;
    @%p bra LOAD_W_DONE;
    add.u32 %r_t0, %r_wbase, %r_idx;
    mul.wide.u32 %rd_addr, %r_t0, 4;
    add.u64 %rd_addr, %rd_addr, %rd_w;
    ld.global.f32 %f_v, [%rd_addr];
    mul.lo.u32 %r_t0, %r_idx, 4;
    add.u32 %r_t0, %r_t0, %r_smw;
    st.shared.f32 [%r_t0], %f_v;
    add.u32 %r_idx, %r_idx, 144;
    bra LOAD_W_LOOP;
LOAD_W_DONE:
    bar.sync 0;
    @%p_skip bra COMPUTE_DONE;
    mov.f32 %f_acc0, 0f00000000;
    mov.f32 %f_acc1, 0f00000000;
    mov.f32 %f_acc2, 0f00000000;
    mov.f32 %f_acc3, 0f00000000;
    // Channel loop: input channel stride 3025*4 = 12100 bytes,
    // weight channel stride 121*4 = 484 bytes.
    mov.u32 %r_c, 0;
    mov.u32 %r_iptr1, %r_iptr;
    mov.u32 %r_wptr1, %r_smw;
LOOP_C:
    // Kernel-row loop: input row stride 55*4 = 220 bytes,
    // weight row stride 11*4 = 44 bytes.
    mov.u32 %r_kh, 0;
    mov.u32 %r_iptr2, %r_iptr1;
    mov.u32 %r_wptr2, %r_wptr1;
LOOP_KH:
    mov.u32 %r_kw, 0;
    mov.u32 %r_ip, %r_iptr2;
    mov.u32 %r_wp, %r_wptr2;
LOOP_KW:
    // One shared input value feeds FOUR filter accumulators.
    ld.shared.f32 %f_v, [%r_ip];
    ld.shared.f32 %f_w0, [%r_wp];
    ld.shared.f32 %f_w1, [%r_wp+1452];
    ld.shared.f32 %f_w2, [%r_wp+2904];
    ld.shared.f32 %f_w3, [%r_wp+4356];
    fma.rn.f32 %f_acc0, %f_v, %f_w0, %f_acc0;
    fma.rn.f32 %f_acc1, %f_v, %f_w1, %f_acc1;
    fma.rn.f32 %f_acc2, %f_v, %f_w2, %f_acc2;
    fma.rn.f32 %f_acc3, %f_v, %f_w3, %f_acc3;
    add.u32 %r_ip, %r_ip, 4;
    add.u32 %r_wp, %r_wp, 4;
    add.u32 %r_kw, %r_kw, 1;
    setp.lt.u32 %p, %r_kw, 11;
    @%p bra LOOP_KW;
    add.u32 %r_iptr2, %r_iptr2, 220;
    add.u32 %r_wptr2, %r_wptr2, 44;
    add.u32 %r_kh, %r_kh, 1;
    setp.lt.u32 %p, %r_kh, 11;
    @%p bra LOOP_KH;
    add.u32 %r_iptr1, %r_iptr1, 12100;
    add.u32 %r_wptr1, %r_wptr1, 484;
    add.u32 %r_c, %r_c, 1;
    setp.lt.u32 %p, %r_c, 3;
    @%p bra LOOP_C;
    // Add biases: k is a multiple of 4, so the 4 biases are 16B aligned.
    mul.wide.u32 %rd_addr, %r_k, 4;
    add.u64 %rd_addr, %rd_addr, %rd_b;
    ld.global.v4.f32 {%f_b0, %f_b1, %f_b2, %f_b3}, [%rd_addr];
    add.f32 %f_acc0, %f_acc0, %f_b0;
    add.f32 %f_acc1, %f_acc1, %f_b1;
    add.f32 %f_acc2, %f_acc2, %f_b2;
    add.f32 %f_acc3, %f_acc3, %f_b3;
    // Store the 4 results; consecutive filters are 3025 elements
    // (12100 bytes) apart in the output tensor.
    mul.wide.u32 %rd_addr, %r_k, 12100;
    add.u64 %rd_addr, %rd_addr, %rd_obase;
    st.global.f32 [%rd_addr], %f_acc0;
    st.global.f32 [%rd_addr+12100], %f_acc1;
    st.global.f32 [%rd_addr+24200], %f_acc2;
    st.global.f32 [%rd_addr+36300], %f_acc3;
COMPUTE_DONE:
    // All threads must finish reading the shared filter weights before
    // the next iteration's cooperative load overwrites them.
    bar.sync 0;
    add.u32 %r_k, %r_k, 4;
    setp.lt.u32 %p, %r_k, 96;
    @%p bra LOOP_K;
    ret;
}
"""
_ptx_module = None
def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module
def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("conv2d_kernel")
class ModelNew(nn.Module):
    def __init__(self, num_classes=1000):
        super().__init__()
        # Match the reference constructor and parameters exactly.
        self.conv1 = nn.Conv2d(in_channels=3, out_channels=96, kernel_size=11, stride=4, padding=2)
    def forward(self, x):
        batch_size = x.shape[0]
        out_h = (x.shape[2] + 2 * 2 - 11) // 4 + 1
        out_w = (x.shape[3] + 2 * 2 - 11) // 4 + 1
        out = torch.empty((batch_size, 96, out_h, out_w), dtype=x.dtype, device=x.device)
        tile = 12
        grid_x = (out_w + tile - 1) // tile
        grid_y = (out_h + tile - 1) // tile
        # Each CTA now covers all 96 filters, so grid.z is just the batch.
        grid_z = batch_size
        module = _get_ptx_module()
        module.launch(
            "conv2d_kernel",
            grid=(grid_x, grid_y, grid_z),
            block=(tile * tile, 1, 1),
            arguments=[x, self.conv1.weight, self.conv1.bias, out],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return out
